from pathlib import Pathfrom PIL import Imagefrom src import maindef create_image(path):    Image.new("RGB", (800, 600)).save(path)def test_discover_posts_detects_individual_images(tmp_path):    site_directory = tmp_path / "AGB"    site_directory.mkdir()    image_1 = site_directory / "73.png"    image_2 = site_directory / "74.png"    create_image(image_1)    create_image(image_2)    posts = main.discover_posts(site_directory)    assert len(posts) == 2    assert posts[0] == [image_1]    assert posts[1] == [image_2]def test_discover_posts_ignores_small_images(tmp_path):    site_directory = tmp_path / "AGB"    site_directory.mkdir()    image = site_directory / "73.png"    small_image = site_directory / "73_small.jpg"    create_image(image)    create_image(small_image)    posts = main.discover_posts(site_directory)    assert len(posts) == 1    assert posts[0] == [image]def test_discover_posts_processes_carousel_as_one_post(tmp_path):    site_directory = tmp_path / "aima"    site_directory.mkdir()    carousel_directory = site_directory / "carrete"    carousel_directory.mkdir()    image_1 = carousel_directory / "40.png"    image_2 = carousel_directory / "41.png"    image_3 = carousel_directory / "42.png"    for image_path in [image_1, image_2, image_3]:        create_image(image_path)    posts = main.discover_posts(site_directory)    assert len(posts) == 1    assert posts[0] == [        image_1,        image_2,        image_3    ]def test_discover_posts_detects_individual_and_carousel_posts(tmp_path):    site_directory = tmp_path / "AGB"    site_directory.mkdir()    individual_image = site_directory / "73.png"    carousel_directory = site_directory / "carrete"    carousel_directory.mkdir()    carousel_image_1 = carousel_directory / "40.png"    carousel_image_2 = carousel_directory / "41.png"    create_image(individual_image)    create_image(carousel_image_1)    create_image(carousel_image_2)    posts = main.discover_posts(site_directory)    assert len(posts) == 2    assert posts[0] == [individual_image]    assert posts[1] == [        carousel_image_1,        carousel_image_2    ]def test_discover_sites_detects_multiple_sites(tmp_path):    main_directory = tmp_path / "clientes"    main_directory.mkdir()    agb_directory = main_directory / "AGB"    agb_directory.mkdir()    aima_directory = main_directory / "aima"    aima_directory.mkdir()    agb_image = agb_directory / "73.png"    aima_image = aima_directory / "40.png"    create_image(agb_image)    create_image(aima_image)    sites = main.discover_sites(main_directory)    assert len(sites) == 2    assert sites[0][0] == "AGB"    assert sites[0][1] == [[agb_image]]    assert sites[1][0] == "aima"    assert sites[1][1] == [[aima_image]]def test_discover_sites_rejects_invalid_directory(tmp_path):    invalid_path = tmp_path / "no_existe"    try:        main.discover_sites(invalid_path)        assert False    except ValueError as error:        assert "La carpeta no existe" in str(error)